        else { s0 = hash(SEED + "|" + seedBase + "|rng"); }
        var a = s0 | 0, own = Math.random;
        Math.random = function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
        try { return fn(); }
        finally {
