        }

        // Live total of the capital the visible choices commit this quarter
        _renderCommit() {
            var el = document.getElementById('commitText');
            if (!el) return;
            var st = window.mySimulation.state;
            if (!st || !st.domainState) return;
            var idx = this._roundIdxNow();
            var round = this.ROUNDS[idx];
            var d = {};
            for (var i = 0; i < round.decisions.length; i++) {
                var sel = document.getElementById('input_' + round.decisions[i].key);
                var v = sel ? parseInt(sel.value, 10) : NaN;
                d[round.decisions[i].key] = isNaN(v) ? -1 : v;
            }
            var cap = this._effects(idx, d, st.domainState).cap;
            var left = 280 - st.domainState.capitalSpent - cap;
            var key = left < 0 ? 'commit_over' : 'commit_line';
            el.textContent = this._fill(key, { c: this._m(cap), l: this._m(Math.abs(left)) });
            el.className = left < 0 ? 'nearshore-sim-commit nearshore-sim-commit-over' : 'nearshore-sim-commit';
        }

        _m(v) { return (Math.round(v * 10) / 10).toString(); }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = window.mySimulation.t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = window.mySimulation.t(round.briefKey);

            var container = document.getElementById('decisionsContainer');
            if (!container) return;
            container.innerHTML = '';

            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
