            }
            return true;
        }

        // The round model, with no side effects: what the six choices of a quarter do,
        // before the event. cap is the capital committed, in millions of dollars.
        // mx is how much Mexico capacity stands behind a move toward Mexico.
        _effects(roundIdx, d, ds) {
            var e = { cost: 0, res: 0, del: 0, flex: 0, cap: 0, cn: 0, mx: 0, us: 0, single: ds.singleSource || 0, second: ds.secondSource || 0, absorbed: ds.absorbed || 0, esg: ds.esgLevel || 0, sunk: 0 };
            // fp collects what the footprint itself does; everything else supports it and counts at SUPPORT strength
