                else if (d.d1 === 1) { e.res += 0.01; }
                if (d.d2 === 1) { e.cap += 4; e.flex += 0.04; e.res += 0.02; }
                if (d.d3 === 1) { e.cap += 1.2; e.res += 0.02; e.flex += 0.02; }
                if (d.d4 === 1) { e.cap += 0.85; e.cost -= 0.5; }
                if (d.d5 === 1) { e.cap += 3.2; e.res += 0.03; e.del += 0.01; }
                else if (d.d5 === 0) { e.cap += 0.2; e.res += 0.01; }
                if (d.d6 === 1) { e.cap += 0.8; e.res += 0.02; }
            }
            else if (roundIdx === 1) {
                var siteCap = 0;
                if (d.d1 === 1) { siteCap = 185; e.cost += 1.0; }
                else if (d.d1 === 2) { siteCap = 165; e.cost += 0.5; }
                e.cap += siteCap;
                if (d.d1 > 0) {
                    // entry mode, product mix and workforce describe the plant: without a site they do nothing
                    if (d.d2 === 1) { e.cost -= 0.5; e.flex += 0.03; }
                    else if (d.d2 === 2) { e.cap += 220 - siteCap; e.cost -= 1.5; e.del += 0.01; }
                    if (d.d3 === 1) { e.cost += 0.5; e.res += 0.01; }
                    else if (d.d3 === 2) { e.cost -= 0.5; e.del += 0.008; e.flex += 0.02; }
                    if (d.d4 === 1) { e.cap += 8; e.res += 0.02; e.del += 0.01; }
                    else if (d.d4 === 2) { e.cost += 0.3; }
                    if (ds.r1MexicoVisit === 1) { e.cost -= 0.8; e.res += 0.01; }
                }
                if (d.d5 === 1) { e.cap += 12; e.cost -= 1.0; e.flex += 0.03; e.res += 0.02; }
                if (d.d6 === 1) { e.cap += 6; e.res += 0.02; e.esg = 1; }
            }
            else if (roundIdx === 2) {
