                k = site === 1 ? 1 : (site === 2 ? (d.d2 === 2 ? 1 : 0.7) : 0.25);
                // the plant committed last quarter comes on line now and takes volume out of China
                if (site === 1) { fp.res += 0.03; fp.del += 0.015; e.cn -= 12; e.mx += 12; }
                else if (site === 2) { fp.res += 0.03; fp.del += 0.005; e.cn -= 10; e.mx += 10; }
                if (d.d1 === 0) { e.cost += 4.0; fp.res -= 0.04; e.absorbed = 1; }
                else if (d.d1 === 1) { e.cap += 25; e.cost += (site > 0 ? 0 : 2.5); fp.res += 0.05 * k; fp.flex += 0.04 * k; e.cn -= 8 * k; e.mx += 5 * k; e.us += 3 * k; e.sunk = 1; }
                else if (d.d1 === 2) { e.cost += 1.5; fp.del -= 0.01; }
                else if (d.d1 === 3) { e.cap += 12; e.cost += 1.0; fp.res += 0.03 * k; fp.flex += 0.02 * k; e.cn -= 5 * k; e.mx += 3 * k; e.us += 2 * k; }
                if (d.d2 === 1) { e.cap += 15; e.cost += 1.5; e.del += 0.015; e.sunk = 1; }
                else if (d.d2 === 2 && site > 0) { e.cap += 10; e.cost -= 0.5; e.del += 0.01; }
                if (d.d3 === 1) { e.res += 0.03; e.del += 0.01; }
                else if (d.d3 === 2 && site > 0) { e.res += 0.04; e.flex += 0.02; }
                else if (d.d3 === 3) { e.cap += 8; e.del += 0.005; }
                if (d.d4 === 1) { e.cap += 78; e.del += 0.02; e.flex += 0.03; e.cost += 0.5; }
                else if (d.d4 === 2) { e.flex += 0.02; }
                if (d.d5 === 1) { e.cap += 2; e.res += 0.02; }
                if (d.d6 === 1) { e.res += 0.02; e.del += 0.01; e.flex += 0.01; }
                if (ds.r1TariffAssess === 2) { e.res += 0.02; e.cost -= 0.5; }
                if (ds.r1Scenario === 1) { e.flex += 0.02; }
                if (ds.r1PoliticalIntel === 1) { e.res += 0.01; }
