            else if (roundIdx === 3) {
                k = site > 0 ? 1 : 0.25;
                // a tariff absorbed last quarter is still being carried in the margin
                if (ds.absorbed === 1) { e.cost += 1.5; }
                if (d.d1 === 0) { fp.res -= 0.05; fp.flex -= 0.02; }
                else if (d.d1 === 1) { e.cost += 1.5 + (site > 0 ? 0 : 1.5); fp.res += 0.04 * k; fp.del += 0.01 * k; fp.flex += 0.03 * k; e.cn -= 5 * k; e.mx += 3 * k; e.us += 2 * k; }
                else if (d.d1 === 2) { e.cost += 4.0 + (site > 0 ? 0 : 2.5); fp.res += 0.06 * k; fp.del += 0.015 * k; fp.flex -= 0.02; e.cn -= 12 * k; e.mx += 10 * k; e.us += 2 * k; }
                if (d.d2 === 0) { e.cost += 0.5; e.single = 0; e.second = 1; }
                else if (d.d2 === 1) { e.cost -= 1.0; e.single = 1; e.second = 0; }
                if (d.d3 === 0) { e.cost += 0.3; }
                else if (d.d3 === 1) { e.cap += 8; e.res += 0.02; e.del += 0.01; }
                else if (d.d3 === 2) { e.cap += 22; e.res += 0.04; e.del += 0.02; e.flex += 0.03; }
                if (d.d4 === 0) { e.flex += 0.01; }
                else if (d.d4 === 1) { e.cap += 115; e.cost -= 2.0; e.res += 0.02; }
                else if (d.d4 === 2) { e.cap += 30; e.del += 0.01; }
                if (d.d5 === 0) { e.flex += 0.02; }
                else if (d.d5 === 1) { e.cap += 120; e.res += 0.03; e.flex += 0.02; e.cost -= 1.5; }
                else if (d.d5 === 2) { e.cap += 180; e.res += 0.04; e.flex += 0.03; e.cost -= 2.5; }
