                k = site > 0 ? 1 : 0.25;
                // and it is carried for a second quarter
                if (ds.absorbed === 1) { e.cost += 1.5; }
                if (d.d1 === 0) { fp.res -= 0.05; fp.flex -= 0.02; }
                else if (d.d1 === 1) { e.cost += 1.5 + (site > 0 ? 0 : 1.5); fp.res += 0.04 * k; fp.del += 0.01 * k; fp.flex += 0.03 * k; e.cn -= 5 * k; e.mx += 5 * k; }
                else if (d.d1 === 2) { e.cost += 4.0 + (site > 0 ? 0 : 2.5); fp.res += 0.06 * k; fp.del += 0.015 * k; fp.flex -= 0.02; e.cn -= 10 * k; e.mx += 8 * k; e.us += 2 * k; }
                if (d.d2 === 1) { e.cap += 18; e.res += 0.02; e.del += 0.01; }
                else if (d.d2 === 2) { e.cap += 45; e.res += 0.04; e.del += 0.02; e.flex += 0.03; }
                if (d.d3 === 1) { e.cost -= 1.0; fp.res -= 0.04; fp.del -= 0.03; fp.flex -= 0.04; }
                else if (d.d3 === 2) { e.cap += 20; e.res += 0.03; e.flex += 0.02; e.del += 0.01; }
                if (d.d4 === 0) { e.del += 0.01; e.flex -= 0.01; }
                else if (d.d4 === 1) { e.del += 0.005; e.flex += 0.02; e.cost += 0.5; }
                else if (d.d4 === 2) { e.flex += 0.01; }
                if (d.d5 === 1) { e.res += 0.03; e.flex += 0.02; }
                else if (d.d5 === 2) { e.res += 0.05; e.flex += 0.03; e.del += 0.01; }
                if (d.d6 === 0) { e.res += 0.01; }
                else if (d.d6 === 1) { e.res += 0.02; e.flex += 0.01; }
                else if (d.d6 === 2) { e.cap += 0.35; e.res += 0.04; e.flex += 0.02; e.del += 0.005; }
                // a single-source base chosen last quarter has no second source to fall back on now
                if (ds.singleSource === 1) { fp.res -= 0.05; fp.del -= 0.05; fp.flex -= 0.07; }
                // the second sources qualified last quarter are usable now
                if (ds.secondSource === 1) { fp.flex += 0.03; }
            }
            e.res = fp.res + SUPPORT * e.res;
            e.del = fp.del + SUPPORT * e.del;
            e.flex = fp.flex + SUPPORT * e.flex;
            return e;
        }

        // How hard an event lands depends on where the volume sits when it happens
        _exposure(evt, ds, eff) {
            var kind = evt.kind || 'all';
            if (kind === 'china') return ds.chinaShare / 42;
            if (kind === 'asia') return (ds.chinaShare + ds.vietnamShare) / 65;
            if (kind === 'mexico') return Math.min(1.5, ds.mexicoShare / 30);
            if (kind === 'usmca') return Math.min(2, (ds.mexicoShare + ds.domesticShare) / 30);
            if (kind === 'esg') return eff.esg >= 2 ? 0 : (eff.esg === 1 ? 0.5 : 1);
            return 1;
        }

        // One function turns the four indicators into the points, the score and the tier
        _score(costIdx, riskSc, delivSc, flexSc) {
            var lin = function (x, pts) {
                // pts: ascending [x, y] anchors, flat outside them
                if (x <= pts[0][0]) return pts[0][1];
                for (var i = 1; i < pts.length; i++) {
                    if (x <= pts[i][0]) {
                        return pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * (x - pts[i - 1][0]) / (pts[i][0] - pts[i - 1][0]);
                    }
                }
                return pts[pts.length - 1][1];
            };
            var c = lin(costIdx, [[106, 30], [118, 0]]);
            var r = lin(riskSc, [[0.62, 0], [0.70, 10], [0.78, 20], [0.85, 30]]);
            var dl = lin(delivSc, [[0.74, 0], [0.82, 8], [0.88, 14], [0.92, 20]]);
            var f = lin(flexSc, [[0.7333, 0], [0.80, 8], [0.85, 14], [0.90, 20]]);
            var total = Math.max(0, Math.min(100, Math.round((c + r + dl + f) * 10) / 10));
            var tier = 'concerning';
            if (total >= 85) tier = 'excellent';
            else if (total >= 70) tier = 'proficient';
            else if (total >= 55) tier = 'developing';
            return { cost: Math.round(c * 10) / 10, res: Math.round(r * 10) / 10, del: Math.round(dl * 10) / 10, flex: Math.round(f * 10) / 10, total: total, tier: tier };
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            return {
                period: out.period,
                costIndex: out.costIndex,
                riskScore: out.riskScore,
                deliveryScore: out.deliveryScore,
                flexScore: out.flexScore,
                capitalSpent: out.capitalSpent,
                event: out.event,
                chinaShare: out.chinaShare,
                mexicoShare: out.mexicoShare,
                capital: out.capital,
                overallScore: out.overallScore,
                score: out.overallScore
            };
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundIdx = Math.min(period - 1, 4);

            var e = this._effects(roundIdx, d, ds);

            if (roundIdx === 0) {
                ds.r1TariffAssess = d.d1;
                ds.r1SupplierDiv = d.d2;
                ds.r1Scenario = d.d3;
                ds.r1MexicoVisit = d.d4;
                ds.r1ChinaAudit = d.d5;
                ds.r1PoliticalIntel = d.d6;
            }
            if (roundIdx === 1) { ds.r2Site = d.d1; }
            ds.singleSource = e.single;
            ds.absorbed = e.absorbed;
            ds.secondSource = e.second;
            ds.esgLevel = e.esg;

            // the volume moves first, so the event meets the footprint the player chose
            ds.chinaShare += e.cn;
            ds.mexicoShare += e.mx;
            ds.domesticShare += e.us;
            ds.chinaShare = Math.max(0, Math.min(100, ds.chinaShare));
            ds.vietnamShare = Math.max(0, Math.min(100, ds.vietnamShare));
            ds.mexicoShare = Math.max(0, Math.min(100, ds.mexicoShare));
            ds.domesticShare = Math.max(0, Math.min(100, ds.domesticShare));
            ds.otherShare = Math.max(0, 100 - (ds.chinaShare + ds.vietnamShare + ds.mexicoShare + ds.domesticShare));

            // capital beyond the approved budget is financed, and the financing shows in the Cost Index
            var overBefore = Math.max(0, ds.capitalSpent - 280);
            ds.capitalSpent += e.cap;
            ds.capital = 280 - ds.capitalSpent;
            var overAfter = Math.max(0, ds.capitalSpent - 280);
            var finCost = 0.05 * (overAfter - overBefore);

            var evt = this._selectEvent(roundIdx);
            var x = this._exposure(evt, ds, e);
            var evCost = evt.costMod * x;
            var evRes = evt.riskMod * x;
            var evDel = evt.delivMod * x;
            var evFlex = evt.flexMod * x;
            // the withdrawn tariff leaves rushed spending stranded
            var sunk = (evt.nameKey === 'r3_e1_name' && e.sunk === 1) ? 1.5 : 0;

            ds.costIndex = Math.max(70, Math.min(130, ds.costIndex + e.cost + finCost + evCost + sunk));
            ds.riskScore = Math.max(0.30, Math.min(1.0, ds.riskScore + e.res + evRes));
            ds.deliveryScore = Math.max(0.70, Math.min(1.0, ds.deliveryScore + e.del + evDel));
            ds.flexScore = Math.max(0.40, Math.min(1.0, ds.flexScore + e.flex + evFlex));

            var sc = this._score(ds.costIndex, ds.riskScore, ds.deliveryScore, ds.flexScore);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: sc.total });
            ds.performanceTier = sc.tier;

            var i = period - 1;
            ds.costHistory[i] = Math.round(ds.costIndex * 10) / 10;
            ds.riskHistory[i] = Math.round(ds.riskScore * 100) / 100;
            ds.deliveryHistory[i] = Math.round(ds.deliveryScore * 1000) / 1000;
            ds.flexHistory[i] = Math.round(ds.flexScore * 100) / 100;
            ds.capitalHistory[i] = Math.round(e.cap * 10) / 10;
            ds.scoreHistory[i] = sc.total;
            ds.eventLog[i] = evt.nameKey;
            ds.roundNotes[i] = {
                evt: evt.nameKey, desc: evt.descKey, kind: evt.kind || 'all', x: Math.round(x * 100) / 100,
                dCost: Math.round((e.cost + finCost) * 10) / 10, dRes: Math.round(e.res * 100) / 100,
                eCost: Math.round((evCost + sunk) * 10) / 10, eRes: Math.round(evRes * 100) / 100,
                fin: Math.round(finCost * 10) / 10, sunk: sunk, cap: Math.round(e.cap * 10) / 10
            };
            ds.costHistory.length = ds.riskHistory.length = ds.deliveryHistory.length = ds.flexHistory.length = period;
            ds.capitalHistory.length = ds.scoreHistory.length = ds.eventLog.length = ds.roundNotes.length = period;

            // snapshot end-of-period domainState for correct Undo (index = period number)
            this._dsSnaps[period] = JSON.parse(JSON.stringify(ds));

            this._renderRoundNote(ds);

            // Render the next briefing and decision form synchronously (deterministic)
            if (state.currentPeriod < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return {
                period: period,
                costIndex: ds.costIndex,
                riskScore: ds.riskScore,
                deliveryScore: ds.deliveryScore,
                flexScore: ds.flexScore,
                capitalSpent: e.cap,
                event: evt.nameKey,
                chinaShare: ds.chinaShare,
                mexicoShare: ds.mexicoShare,
                capital: ds.capital,
                overallScore: sc.total
            };
        }

        _sgn(v, digits) {
            var s = Math.abs(v).toFixed(digits);
            return (v < 0 ? '−' : '+') + s;
        }

        // What happened last quarter and why: the event, how exposed the footprint was, and the split
        // between what the choices moved and what the event moved. Stays on screen until the next submit.
        _renderRoundNote(ds) {
            var panel = document.getElementById('eventPanel');
            var text = document.getElementById('eventText');
            if (!panel || !text || !ds) return;
            var notes = ds.roundNotes || [];
            if (!notes.length) { panel.style.display = 'none'; text.textContent = ''; return; }
            var n = notes[notes.length - 1];
            var html = '<strong>' + this._t(n.evt) + ':</strong> ' + this._t(n.desc);
            if (n.kind !== 'all') {
                html += ' <span class="nearshore-sim-note-line">' + this._fill('note_x_' + n.kind, { x: Math.round(n.x * 100) }) + '</span>';
            }
            html += '<span class="nearshore-sim-note-line">' + this._fill('note_split', {
                q: notes.length, dc: this._sgn(n.dCost, 1), dr: this._sgn(n.dRes, 2), ec: this._sgn(n.eCost, 1), er: this._sgn(n.eRes, 2)
            }) + '</span>';
            if (n.fin > 0) html += '<span class="nearshore-sim-note-line">' + this._fill('note_fin', { f: this._sgn(n.fin, 1) }) + '</span>';
            if (n.sunk > 0) html += '<span class="nearshore-sim-note-line">' + this._fill('note_sunk', { f: this._sgn(n.sunk, 1) }) + '</span>';
            panel.style.display = 'block';
            text.innerHTML = html;
        }

