        // Reads the run from its history: what was chosen, what it led to, where it turned
        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var last = history[history.length - 1];
            var r = last.results || {};
            var ds = last.domainState || {};

            var costIdx = typeof r.costIndex === 'number' ? r.costIndex : 100;
            var riskSc = typeof r.riskScore === 'number' ? r.riskScore : 0.65;
            var delivSc = typeof r.deliveryScore === 'number' ? r.deliveryScore : 0.913;
            var flexSc = typeof r.flexScore === 'number' ? r.flexScore : 0.72;
            var sc = this._score(costIdx, riskSc, delivSc, flexSc);

            var dec = function (q) { return (history[q - 1] && history[q - 1].decisions) || null; };
            var q1 = dec(1), q2 = dec(2), q3 = dec(3), q4 = dec(4), q5 = dec(5);
            var spent = typeof ds.capitalSpent === 'number' ? ds.capitalSpent : 0;
            var flags = {
                noSite: !!(q2 && q2.d1 === 0),
                claim: !!(q2 && q2.d1 === 0 && q3 && q3.d3 === 2),
                absorbed: !!(q3 && q3.d1 === 0),
                asiaDom: !!(q4 && q5 && q4.d1 === 0 && q5.d1 === 0),
                allMexico: !!(q4 && q5 && q4.d1 === 2 && q5.d1 === 2),
                single: !!((q4 && q4.d2 === 1) || (q5 && q5.d3 === 1)),
                over: spent > 280
            };

            var insights = [];
            if (flags.noSite) insights.push(this._t(flags.claim ? 'ins_wait_claim' : 'ins_wait'));
            if (flags.absorbed) insights.push(this._t('ins_absorb'));
            if (flags.asiaDom) insights.push(this._fill('ins_asia', { a: Math.round((ds.chinaShare || 0) + (ds.vietnamShare || 0)), r: riskSc.toFixed(2) }));
            if (flags.allMexico && (ds.mexicoShare || 0) >= 30) insights.push(this._fill('ins_mexico', { c: costIdx.toFixed(1), m: Math.round(ds.mexicoShare || 0) }));
            if (flags.single) insights.push(this._fill('ins_single', { d: (delivSc * 100).toFixed(1) }));
            if (flags.over) insights.push(this._fill('ins_over', { o: Math.round(spent - 280), p: (0.05 * (spent - 280)).toFixed(1) }));
            if (history.length >= 5) {
                insights.push(this._fill('ins_footprint', {
                    cn: Math.round(ds.chinaShare || 0), vn: Math.round(ds.vietnamShare || 0), mx: Math.round(ds.mexicoShare || 0)
                }));
            }
            if (costIdx > 107 && !flags.allMexico) insights.push(this._t('insight_cost_exceeded'));
            if (riskSc < 0.78 && !flags.asiaDom) insights.push(this._t('insight_resilience_below'));
            if (delivSc < 0.88 && !flags.single) insights.push(this._t('insight_delivery_needs_improvement'));
            if (flexSc < 0.80) insights.push(this._t('insight_flex_low'));
            if (sc.total >= 85) insights.push(this._t('insight_outstanding'));
            insights = insights.slice(0, 5);

            // turning point: the quarter where the score moved least in the player's favour
            var sh = ds.scoreHistory || [];
            var notes = ds.roundNotes || [];
            var turn = null;
            if (sh.length >= 2) {
                var worst = 1, worstDelta = sh[1] - sh[0];
                for (var i = 2; i < sh.length; i++) {
                    if (sh[i] - sh[i - 1] < worstDelta) { worstDelta = sh[i] - sh[i - 1]; worst = i; }
                }
                var n = notes[worst] || {};
                turn = this._fill(worstDelta < 0 ? 'turn_down' : 'turn_flat', {
                    q: worst + 1, a: sh[worst - 1].toFixed(1), b: sh[worst].toFixed(1),
                    ev: n.evt ? this._t(n.evt) : '', dc: this._sgn(n.dCost || 0, 1), ec: this._sgn(n.eCost || 0, 1),
                    dr: this._sgn(n.dRes || 0, 2), er: this._sgn(n.eRes || 0, 2)
                });
            }

            var checks = 0;
            if (q1 && (q1.d1 === 2 || q1.d3 === 1)) checks++;
            if (q2 && q2.d1 > 0) checks++;
            if (!flags.single) checks++;
            if (!flags.over) checks++;

            return {
                totalScore: sc.total,
                overallScore: sc.total,
                composite: sc.total,
                score: sc.total,
                costIndex: costIdx,
                riskScore: riskSc,
                deliveryScore: delivSc,
                flexScore: flexSc,
                capitalSpent: spent,
                points: { cost: sc.cost, res: sc.res, del: sc.del, flex: sc.flex },
                processChecks: checks,
                performance: sc.tier,
                performanceKey: 'perf_' + sc.tier,
                performanceLabel: this._t('perf_' + sc.tier),
                turningPoint: turn,
                events: (ds.eventLog || []).map(function (k) { return self._t(k); }),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            if (typeof summary.totalScore !== 'number') {
                return '<div class="nearshore-cm"><p>' + this._t('cm_done') + '</p></div>';
            }
            var p = summary.points || {};
            var h = '<div class="nearshore-cm">';
            h += '<p class="nearshore-cm-score"><strong>' + summary.totalScore.toFixed(1) + ' / 100</strong> · ' + summary.performanceLabel + '</p>';
            h += '<table class="nearshore-cm-kpis"><thead><tr><th scope="col">' + this._t('cm_kpi') + '</th><th scope="col">' + this._t('cm_final') + '</th><th scope="col">' + this._t('cm_target') + '</th><th scope="col">' + this._t('cm_points') + '</th></tr></thead><tbody>';
            h += '<tr><th scope="row">' + this._t('cost_index_label') + '</th><td>' + summary.costIndex.toFixed(1) + '</td><td>≤ 106</td><td>' + p.cost + ' / 30</td></tr>';
            h += '<tr><th scope="row">' + this._t('risk_label') + '</th><td>' + summary.riskScore.toFixed(2) + '</td><td>≥ 0.85</td><td>' + p.res + ' / 30</td></tr>';
            h += '<tr><th scope="row">' + this._t('delivery_label') + '</th><td>' + (summary.deliveryScore * 100).toFixed(1) + '%</td><td>≥ 92%</td><td>' + p.del + ' / 20</td></tr>';
            h += '<tr><th scope="row">' + this._t('flex_label') + '</th><td>' + Math.round(summary.flexScore * 100) + '%</td><td>≥ 90%</td><td>' + p.flex + ' / 20</td></tr>';
            h += '</tbody></table>';
            h += '<p>' + this._fill('cm_process', { n: summary.processChecks, s: Math.round(summary.capitalSpent) }) + '</p>';
            if (summary.events && summary.events.length) h += '<p>' + this._t('cm_events') + ' ' + summary.events.join(' → ') + '</p>';
            if (summary.turningPoint) h += '<h4>' + this._t('cm_turn') + '</h4><p>' + summary.turningPoint + '</p>';
            if (summary.insights && summary.insights.length) {
                h += '<h4>' + this._t('cm_insights') + '</h4><ul>';
                for (var i = 0; i < summary.insights.length; i++) h += '<li>' + summary.insights[i] + '</li>';
