            }
            h += '<h4>' + this._t('cm_questions') + '</h4><ol><li>' + this._t('cm_q1') + '</li><li>' + this._t('cm_q2') + '</li><li>' + this._t('cm_q3') + '</li></ol>';
            h += '</div>';
            return h;
        }

